import { MorphLoader } from "@/components/design-for-ai/feedback-morph-loader";

// Drive it from your request state; it keeps its size through every status.
<MorphLoader status={upload.status} label="Uploading brand-kit.zip" successLabel="Uploaded" errorLabel="Upload failed" />

// Inside a button, beside the label, inheriting its colour.
<button className="inline-flex items-center gap-2">
  <MorphLoader status="loading" size={14} strokeWidth={1.5} announce={false} />
  Saving
</button>

<MorphLoader status="loading" size={48} strokeWidth={2.4} shapes={["circle", "hexagon", "diamond"]} speed={0.8} />
